#!/usr/bin/env python3
"""Trace-derived summary; retain negative cases and avoid physical-busy claims."""
import argparse,csv,hashlib,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--out',required=True);a=p.parse_args();out=Path(a.out).resolve()
c=json.loads((out/'comparison.json').read_text());tests=json.loads((out/'tests.json').read_text())
lines=['# Multi-NPU Relay: executed results','','All 48 runs passed normal and optimized independent event/payload verification. Eight live fault injections, idempotent duplicate notifications, payload/event tampering tests, extracted-source graph checks and all prior milestone regressions passed. No fixed-matrix failure or skipped case.','', '| Case | NoBalance µs | Direct µs | TwoStage µs | Chunk µs | Direct/Chunk | Chunk weight µs | Replicas | Native admitted overlaps |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for name,b in c.items():
 d=b['direct'];s=b['chunk-streaming'];lines.append('| '+name+' | '+' | '.join(f"{b[m]['layer_latency_ps']/1e6:.6f}" for m in ['no-balancing','direct','two-stage','chunk-streaming'])+f" | {d['layer_latency_ps']/s['layer_latency_ps']:.4f} | {s['weight_target_duration_ps']/1e6:.6f} | {s['replicas']} | {len(s['native_pipeline_overlaps'])} |")
lines+=['','LayerLatency is layer_start through final source top-k Combine receipt. Weight duration is planning_end through all final target weights ready. A native admitted overlap is a positive intersection between a relay outgoing chunk interval (first native TA admission→target-ready) and a later incoming chunk interval for the same relay. Both edges have entered the native transport, not merely been submitted as WQEs. Counts are witness counts, not disjoint physical busy intervals or link utilization. Submission-based task-lifetime overlaps are separately retained in summaries.','', '## EP64 evidence','', '| Strategy | Weight WQEs | Weight TAs | Total weight bytes | Max NPU weight send bytes | Weight finish µs |','|---|---:|---:|---:|---:|---:|']
for m,b in c['fixed64'].items():lines.append(f"| {m} | {b['weight_WQEs']} | {b['weight_TAs']} | {b['weight_bytes']} | {max(b['weight_send_bytes_per_npu'])} | {b['weight_target_duration_ps']/1e6:.6f} |")
s=c['fixed64']['chunk-streaming'];nb=c['fixed64']['no-balancing'];d=c['fixed64']['direct']
lines+=['',f"EP64 has {s['replicas']} replicas and unchanged balanced max NPU load {s['max_npu_load']} (NoBalance {nb['max_npu_load']}). Direct/Chunk layer ratio is {d['layer_latency_ps']/s['layer_latency_ps']:.4f}×, while NoBalance/Chunk is {nb['layer_latency_ps']/s['layer_latency_ps']:.4f}×. Relay improves this Direct comparison but still loses to NoBalance for this small synthetic workload. No parameters were adjusted after observing results.", '', '## Correctness and public-source checks','',f"The extracted selection oracle passed {tests['public_oracle_cases']} fixed-seed multi-expert cases plus all matrix graphs. {tests['order_sensitive_cases']} cases distinguish original l2p order from rank-sorted order; {tests['cross_expert_load_sensitive_cases']} distinguish persistent cross-expert load from resetting it. Adaptive and public force modes, direct fallbacks and whole/chunk grouping equality are covered.", '', 'All three balanced modes copy the exact same Planner plan bytes and preserve assignments, compute loads and final Combine payload hashes. NoBalance also produces the same logical Combine payloads. Native Direct latency/load matches the accepted single-replica, multi-replica and EP64 evidence exactly. Duration/Compute code and the original PoC coverage tracker remain unchanged.', '', 'Live faults reject corrupted source bytes, corrupted forwarding bytes, corrupted stored relay buffer, early relay send, early final weight ready, premature edge ready, duplicate sending, and fast-relay sends before group completion. Duplicate target notifications are idempotent and reproduce identical latency/results. Tail/bounds/conflicting duplicate coverage tests pass; explicit delayed first-chunk execution proves out-of-order target completion without premature final ready.', '', 'The full accepted Direct 26-run matrix and ordinary/optimized checks were rerun, followed by its complete Planner, NoBalancing, Chunk Relay and legacy parity regressions. Earlier milestone evidence outside this relay package is unchanged. See prior-regression/ for commands, summaries and raw artifact hashes.', '', '## Group-readiness acceptance correction','', 'Correctness and dependency predictions matched for every row. The multi4_force and EP64 streaming cases exhibit positive in-flight overlap. Single-replica and zero-slot fallbacks correctly show none; the public chunk-size case does not exhibit the measured later-chunk overlap. Performance was explicitly unbounded: tail4 ChunkStreaming is slower than both Direct and TwoStage, and the two-stage 4-NPU case is slower than Direct. These results are retained.', '', f"ChunkStreaming now waits for all Stage-I selected relay targets in each expert/shard/chunk group. The slow_relay8 case holds rank 1 target completions for 20 µs: the fast rank 2 relay waits up to {tests['slow_relay_max_fast_wait_ps']/1e6:.6f} µs after its own chunk is ready. The early-group live fault attempts forwarding after local readiness but before group readiness and is rejected. Every group event is independently checked against the maximum target completion of all its Stage-I edges.", '', 'The previous per-relay implementation and raw results remain in commit 167ffee211bafa114ccb627d6b2230bd4a02acc9; attributing that simplification to the user was incorrect. This acceptance correction uses application-layer aggregation and requires no UB protocol changes. Per-relay streaming is no longer selectable. TwoStage retains its requested per-relay whole-expert ablation.', '', 'Pinned selection/grouping and group-ready dependency are preserved. GPU multi-destination tile copies, persistent GPU scheduling, flag visibility latency and memory effects remain abstractions; README details these limits. Synthetic model/network assumptions and unchanged compute limit performance conclusions.', '', '## Evidence navigation','', '`comparison.json` and each summary include all NPU send-byte vectors, WQE/TA counts, target-weight time, layer time, replica count and overlap witness task IDs. `group-timeline.csv` records each actual group-ready event, Stage-I task set and slow/fast target gap. `relay-timeline.csv` joins every weight send/target-ready/sender completion with its global byte range, source/destination physical ID and dependency list. Each case retains executed-transfers.csv, events.csv, native traces, actual received-payloads.bin and payload-index.csv. SHA-256 inventory covers all delivered evidence.']
report='\n'.join(lines)+'\n';(out/'REPORT.md').write_text(report)
if out==Path(__file__).resolve().parent/'evidence':(out.parent/'REPORT.md').write_text(report)
with (out/'relay-timeline.csv').open('w') as f:
 fields=['case','mode','task','source','target','source_physical','physical','offset','bytes','dependencies','send_ps','target_ready_ps','sender_complete_ps']
 writer=csv.DictWriter(f,fieldnames=fields,lineterminator='\n');writer.writeheader()
 for name in c:
  for mode in c[name]:
   case=out/name/mode;config=json.loads((case/'config.json').read_text())
   with (case/'events.csv').open() as ef:events=list(csv.DictReader(ef))
   times={(int(x['task']),x['event']):int(x['time_ps']) for x in events if x['task']!='-1'}
   for x in config['transfers']:
    if x['stage']!=2:continue
    row={k:x[k] for k in ['task','source','target','source_physical','physical','offset','bytes']};row.update(case=name,mode=mode,dependencies=';'.join(map(str,x['dependencies'])),send_ps=times[x['task'],'send'],target_ready_ps=times[x['task'],'edge_ready'],sender_complete_ps=times[x['task'],'sender_complete']);writer.writerow(row)
with (out/'group-timeline.csv').open('w') as f:
 fields=['case','expert','offset','bytes','stage1_tasks','relay_targets','first_target_ready_ps','group_ready_ps','max_fast_relay_wait_ps']
 writer=csv.DictWriter(f,fieldnames=fields,lineterminator='\n');writer.writeheader()
 for name in c:
  case=out/name/'chunk-streaming';config=json.loads((case/'config.json').read_text());plan=json.loads((case/'plan.json').read_text());physical={x['id']:x for x in plan['physical']}
  with (case/'events.csv').open() as ef:events=list(csv.DictReader(ef))
  ready={int(x['task']):int(x['time_ps']) for x in events if x['event']=='edge_ready'}
  for event in events:
   if event['event']!='group_chunk_ready':continue
   expert,offset,size=map(int,(event['id'],event['offset'],event['bytes']))
   seeds=[x for x in config['transfers'] if x['stage']==2 and physical[x['source_physical']]['kind']=='main' and physical[x['physical']]['expert']==expert and x['offset']==offset and x['bytes']==size]
   first=min(ready[x['task']] for x in seeds);group=int(event['time_ps'])
   writer.writerow(dict(case=name,expert=expert,offset=offset,bytes=size,stage1_tasks=';'.join(str(x['task']) for x in seeds),relay_targets=';'.join(str(x['target']) for x in seeds),first_target_ready_ps=first,group_ready_ps=group,max_fast_relay_wait_ps=group-first))
files=sorted(f for f in out.rglob('*') if f.is_file() and f.name!='artifact-sha256.json')
(out/'artifact-sha256.json').write_text(json.dumps({str(f.relative_to(out)):hashlib.sha256(f.read_bytes()).hexdigest() for f in files},indent=2)+'\n')
if out==Path(__file__).resolve().parent/'evidence':(out.parent/'run-ledger.md').write_text('# Run ledger\n\n48/48 fixed runs passed. Negative performance retained. Exact commands, return codes and trace-derived summaries: evidence/run-ledger.json. All old regressions passed.\n')
print('Report and evidence manifest written:',out)
